void UCDHudGen::Draw_BP_QueueHUD(ACDHudBase* Hud, int32 SizeX, int32 SizeY)
{
	using namespace CDHudGen_BP_QueueHUD;
	ACDHudBase* Self = Hud;
	if (!Self) { return; }
	FState* St = &StateFor(Self);
	const int32 Epoch = UCDHudLayers::GetLayerEpoch(LayerName());
	if (St->Epoch != Epoch) { St->ResetValues(); St->Epoch = Epoch; }   // fresh frame after a switch (rule R3)
	FCtx C{ Self, *St };
	C.S.o_CX_1_SizeX = SizeX; C.S.o_CX_1_SizeY = SizeY;
	N_CX_2(C);
}